    .map(r => ({ code: s_(r[CPC['Code']]), pct: n_(r[CPC['Percent']]), min: n_(r[CPC['Min bill ₹']]), till: ymd_(r[CPC['Valid till']]),
      lucky: /^LD/.test(s_(r[CPC['Code']])), next: /^LD/.test(s_(r[CPC['Code']])) && ymd_(r[CPC['Issued at']]) >= ymd_(new Date()),
