const PSC = {}; PS_H.forEach((h, i) => PSC[h] = i);
function qbStockFrom_() { return PropertiesService.getScriptProperties().getProperty('QB_STOCK_FROM') || '2026-10-21 03:27'; }
/** d = {bills:[{id, inv, date, time, loc, by, gross, tax, disc, pay:{cash, upi, supi, card, other}, status:'Sale'|'Returned', items:[{pid, sku, name, qty, amount, tax, disc}]}]} */
function posImport_(d, user) {
