  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const have = {}; xrows_(PS_TAB, PS_H).forEach(r => have[s_(r[0])] = 1);
    let ps = productRows_();
    const norm = x => norm_(String(x || '').replace(/\(loose\)/i, '').replace(/\b(21\/25|26\/28)\b/g, '').replace(/(\d+)\s*GM?\b/i, '$1G'));
    const byName = {}; ps.forEach(r => { const k = norm(r[PC.name]) + '|' + (s_(r[PC.unit]) || 'kg'); if (!byName[k]) byName[k] = s_(r[PC.sku]); });
    const bills = (d.bills || []).filter(b => b && b.id && !have[b.id]);
    // items QueueBuster sells that the app does not have yet → other-brand products (priced as billed)
    const skuOf = it => { const u = it.unit === 'kg' ? 'kg' : 'pcs'; return (it.sku && ps.some(r => s_(r[PC.sku]) === it.sku)) ? it.sku : (byName[norm(it.name) + '|' + u] || ''); };
    const missing = {}; bills.forEach(b => b.items.forEach(it => { if (!skuOf(it) && !/hamper|^nutvique/i.test(it.name)) missing[norm(it.name)] = it; }));   // only other brands are added automatically
    const added = Object.keys(missing).length ? addExternalProducts_(Object.keys(missing).map(k => { const it = missing[k], p = Math.round((n_(it.amount) + n_(it.tax) + n_(it.disc)) / (n_(it.qty) || 1));
      return { name: it.name, unit: it.unit === 'kg' ? 'kg' : 'pcs', mrp: p, sell: p, gst: 5, note: 'Added from QueueBuster sales (' + ymd_(new Date()) + ') – check price, HSN and barcode.' }; })) : [];
    if (added.length) { ps = productRows_(); ps.forEach(r => { const k = norm(r[PC.name]) + '|' + (s_(r[PC.unit]) || 'kg'); if (!byName[k]) byName[k] = s_(r[PC.sku]); }); bumpVer_('PRODUCTS_VER', null); }
    const P = {}; ps.forEach(r => P[s_(r[PC.sku])] = r);
    // app bills by store + day → item lists, to spot sales billed in both systems
    const appLines = {}; brows_('lines').forEach(r => { if (s_(r[BH.lines.length - 1]) === 'Cancelled') return; (appLines[s_(r[0])] = appLines[s_(r[0])] || []).push(s_(r[4]) + '@' + round3_(n_(r[8]))); });
    const appBills = {}; brows_('bills').forEach(r => { if (s_(r[BC['Status']]) === 'Cancelled') return; const k = s_(r[BC['Location']]) + '|' + ymd_(r[BC['Date']]);
      (appBills[k] = appBills[k] || []).push({ no: s_(r[BC['Bill no.']]), sig: (appLines[s_(r[BC['Bill no.']])] || []).sort().join(','), used: false }); });
    const from = qbStockFrom_(), now = new Date(), sRows = [], lRows = [], ledger = [];
    const out = { bills: 0, returned: 0, alsoInApp: [], stockLines: 0, added: added.filter(a => !a.existing).map(a => a.name), unmatched: [] };
    bills.forEach(b => {
      const items = b.items.map(it => Object.assign({}, it, { sku: skuOf(it) }));
      items.forEach(it => { if (!it.sku && !/hamper/i.test(it.name)) out.unmatched.push(it.name); if (/hamper/i.test(it.name) && !it.sku) it.sku = byName[norm(it.name) + '|pcs'] || ''; });
