        if (cand) { cand.used = true; status = 'Also billed in app'; note = 'Same items as app bill ' + cand.no; out.alsoInApp.push(b.inv + ' = ' + cand.no); }
      }
      const moves = status === 'Sale' && (b.date + ' ' + b.time) >= from && LOCATIONS.indexOf(b.loc) >= 0;
      const p = b.pay || {}, total = n_(b.gross);
      sRows.push([b.id, String(b.inv), b.date, b.time, b.loc, b.by, items.length, round2_(total + n_(b.disc)), n_(b.disc), n_(b.tax), total, n_(p.cash), round2_(n_(p.upi) + n_(p.supi)), n_(p.card), round2_(n_(p.other) + n_(p.pending)),
        ['cash', 'upi', 'supi', 'card', 'other', 'pending'].filter(k => n_(p[k])).map(k => ({ cash: 'Cash', upi: 'UPI', supi: 'Static UPI', card: 'Card', other: 'Other', pending: 'Pending' }[k])).join(' + ') || (total ? '' : 'No charge'),
        status, moves ? 'Yes' : 'No', note, now]);
      items.forEach(it => {
        const r = P[it.sku], unit = r ? (s_(r[PC.unit]) || 'kg') : (it.unit || 'pcs');
