        if (moves && r && !/^NV-HMP-/.test(it.sku)) { ledger.push(ledgerRow_(b.date, b.loc, 'Sale (QueueBuster)', r, -Math.abs(round3_(n_(it.qty))), 'INV-QB-' + b.id, 'QueueBuster', 'Bill ' + b.inv + ' ' + b.time, 'QueueBuster', now)); out.stockLines++; }
      });
