    if (sRows.length) { const sh = xtab_(PS_TAB, PS_H); sh.getRange(sh.getLastRow() + 1, 1, sRows.length, PS_H.length).setValues(sRows); }
    if (lRows.length) { const sh = xtab_(PL_TAB, PL_H); sh.getRange(sh.getLastRow() + 1, 1, lRows.length, PL_H.length).setValues(lRows); }
