function upiOn_() { return String(setting_('UPI email check', 'Off')) === 'On'; }
function upiMailOn_() { return String(setting_('UPI email search', '') || '').trim().toLowerCase() !== 'off'; }
/** Reads one alert email. Returns null when it is not a credit. */
function upiParse_(subject, body) {
