// ───────────────────────────── ICICI credit SMS → app (v18.21, 28 Oct 2026) ─────────────────────────────
// The owner's iPhone runs a Shortcuts automation "when a message containing 'credited' arrives" that POSTs
// {action:'upiSms', k:<secret>, text:<message>} to the web app. Only ICICI credits to the current account ending in the
// set digits (default 570 = …6570) are kept; personal bank SMS are ignored. Rows go to "UPI Payments" like the email route.
function upiHookKey_() {
  const p = PropertiesService.getScriptProperties(); let k = p.getProperty('UPI_HOOK_KEY');
  if (!k) { k = Utilities.getUuid().replace(/-/g, '').slice(0, 20); p.setProperty('UPI_HOOK_KEY', k); }
  return k;
}
function upiSms_(req) {
  const d = req.data || {}, k = s_(req.k || d.k), text = String(req.text || d.text || '').slice(0, 1000);
  const want = PropertiesService.getScriptProperties().getProperty('UPI_HOOK_KEY');
  if (!want || k !== want) throw new Error('Not allowed.');
  const c = CacheService.getScriptCache(), n = Number(c.get('upisms_n') || 0); if (n > 120) throw new Error('Too many messages.'); c.put('upisms_n', String(n + 1), 60);
  if (!/icici/i.test(text)) return { kept: false, why: 'not ICICI' };
  const acct = String(setting_('UPI SMS account ends with', '570') || '570').replace(/\D/g, '');
  const masks = text.match(/(?:a\/?c(?:ct)?\.?|account)\s*(?:no\.?)?\s*[:\-]?\s*[x*.]*\s*(\d{3,6})/ig) || text.match(/[xX*]{2,}\d{3,6}/g) || [];
  if (acct && masks.length && !masks.some(m => (m.match(/\d+$/) || [''])[0].slice(-acct.length) === acct)) return { kept: false, why: 'other account' };
  const p = upiParse_('', text); if (!p) return { kept: false, why: 'not a credit' };
  const id = 'SMS-' + (p.rrn || Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, text).map(b => ((b + 256) % 256).toString(16).padStart(2, '0')).join('').slice(0, 12));
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const sh = xtab_(UP_TAB, UP_H), rows = xrows_(UP_TAB, UP_H);
    if (rows.some(r => s_(r[6]) === id || (p.rrn && s_(r[4]) === p.rrn))) return { kept: false, why: 'already have it' };
    sh.getRange(sh.getLastRow() + 1, 1, 1, UP_H.length).setValues([[new Date(), p.amount, p.from, p.vpa, p.rrn, 'SMS (iPhone)', id, '', '', '', 'Unmatched', txt_(text, 600)]]);
    sh.getRange(2, 1, sh.getLastRow() - 1, 1).setNumberFormat('dd-mmm-yy hh:mm:ss');
  } finally { lock.releaseLock(); }
  return { kept: true, amount: p.amount, from: p.from || p.vpa, ref: p.rrn };
}

