  if (!user || (user.role !== 'Owner' && user.role !== 'Manager')) throw new Error('Only managers and the owner can move a bill to another store.');
  const reason = txt_(d.reason, 200); if (!reason) throw new Error('Type why the bill is moved (e.g. billed at Gulshan by mistake, sale was at City Galleria).');
