const CORP_LOC = 'Corporate';
const CORP_PROMPT = `You read an Indian GST SALES invoice made in Tally by Nutzy Foods Pvt Ltd (brand Nutvique) for a corporate customer.
Return ONLY JSON (numbers as numbers): {"invoice_no":"","invoice_date":"YYYY-MM-DD","customer":"","customer_gstin":"","place_of_supply":"",
"lines":[{"description":"item text as printed","hsn":"","qty":0,"unit":"PCS/KGS/NOS/BOX","rate":0,"amount":0,"gst_pct":0}],
"taxable_value":0,"cgst":0,"sgst":0,"igst":0,"round_off":0,"total":0}. amount = line value before GST as printed. Use 0 for anything missing.`;
